  store.Settings.SizePercent=200;Changed();if(!CrosshairOverlay.GetWindowRect(overlay.Handle,out rect)||rect.Left!=expected.X-320||rect.Top!=expected.Y-320||rect.Right-rect.Left!=640||rect.Bottom-rect.Top!=640)throw new Exception("Resized overlay lost its center or bounds");randomizer.InstantShortcut();if(store.Settings.SizePercent!=200)throw new Exception("Randomizer reset overlay size");store.Settings.SizePercent=100;store.Settings.WidthPercent=150;store.Settings.HeightPercent=125;Changed();randomizer.InstantShortcut();if(store.Settings.WidthPercent!=150||store.Settings.HeightPercent!=125)throw new Exception("Randomizer reset stretch proportions");if(!CrosshairOverlay.GetWindowRect(overlay.Handle,out rect)||rect.Left!=expected.X-240||rect.Top!=expected.Y-240||rect.Right-rect.Left!=480)throw new Exception("Stretched overlay lost its center");store.Settings.WidthPercent=store.Settings.HeightPercent=100;Changed();
  overlay.SetEnabled(false);if(overlay.Visible)throw new Exception("Crosshair overlay did not hide");await randomizer.Verify();preview.ExportPng(Path.Combine(folder,"crosshair-export.png"));RenderSaved();
 }
